using System.Security.Claims;
using Npgsql;
namespace Bck.Api.Features.ServiceSessions;
public static class ServiceSessionEndpoints
{
 public static RouteGroupBuilder MapServiceSessionEndpoints(this RouteGroupBuilder api){api.MapPost("/service-sessions",OpenAsync);api.MapGet("/service-sessions/{id:guid}",GetAsync);api.MapGet("/service-sessions/{id:guid}/history",GetHistoryAsync);api.MapPut("/service-sessions/{id:guid}/notes",UpdateNotesAsync);api.MapGet("/appointments/{appointmentId:guid}/service-session",GetByAppointmentAsync);api.MapPost("/service-sessions/{id:guid}/items",AddItemAsync);api.MapPost("/service-sessions/{id:guid}/finish",FinishAsync);return api;}
 private static async Task<IResult> OpenAsync(OpenServiceSessionRequest request,HttpRequest httpRequest,ClaimsPrincipal user,ServiceSessionService service,IConfiguration configuration,CancellationToken ct){try{var professionalId=await AppointmentProfessionalAsync(request.AppointmentId,GroupId(user),configuration,ct);if(professionalId is null)return Results.NotFound();if(!CanAccess(user,professionalId.Value))return Results.Forbid();var key=ServiceSessionIdempotency.RequireKey(httpRequest);var result=await service.OpenAsync(GroupId(user),UserId(user),request,key,ct);return Results.Created($"/api/v1/service-sessions/{result.Id}",result);}catch(KeyNotFoundException){return Results.NotFound();}catch(UnauthorizedAccessException){return Results.Forbid();}catch(ArgumentException ex)when(ex.Message is "IDEMPOTENCY_KEY_REQUIRED" or "IDEMPOTENCY_KEY_INVALID"){return Results.BadRequest(new{code=ex.Message,message="A abertura exige uma chave de idempotência válida."});}catch(InvalidOperationException ex)when(ex.Message is "IDEMPOTENCY_KEY_REUSED" or "IDEMPOTENCY_REQUEST_IN_PROGRESS"){return Results.Conflict(new{code=ex.Message,message="A chave de idempotência já está associada a outra abertura ou ainda está em processamento."});}catch(InvalidOperationException ex)when(ex.Message=="SERVICE_SESSION_ALREADY_EXISTS"){return Results.Conflict(new{code=ex.Message,message="Este agendamento já possui atendimento aberto."});}catch(InvalidOperationException ex)when(ex.Message=="APPOINTMENT_NOT_OPENABLE"){return Results.Conflict(new{code=ex.Message,message="O estado atual do agendamento não permite abrir atendimento."});}}
 private static async Task<IResult> GetAsync(Guid id,ClaimsPrincipal user,ServiceSessionService service,CancellationToken ct){var result=await service.GetAsync(GroupId(user),id,ct);if(result is null)return Results.NotFound();if(!CanAccess(user,result.ProfessionalUserId))return Results.Forbid();return Results.Ok(result);}
 private static async Task<IResult> GetHistoryAsync(Guid id,ClaimsPrincipal user,ServiceSessionService service,CancellationToken ct){var current=await service.GetAsync(GroupId(user),id,ct);if(current is null)return Results.NotFound();if(!CanAccess(user,current.ProfessionalUserId))return Results.Forbid();var history=await service.GetHistoryAsync(GroupId(user),id,ct);return history is null?Results.NotFound():Results.Ok(history);}
 private static async Task<IResult> UpdateNotesAsync(Guid id,UpdateServiceSessionNotesRequest request,ClaimsPrincipal user,ServiceSessionService service,CancellationToken ct){var current=await service.GetAsync(GroupId(user),id,ct);if(current is null)return Results.NotFound();if(!CanAccess(user,current.ProfessionalUserId))return Results.Forbid();try{return Results.Ok(await service.UpdateNotesAsync(GroupId(user),id,UserId(user),request,ct));}catch(InvalidOperationException ex)when(ex.Message=="SERVICE_SESSION_CLOSED"){return Results.Conflict(new{code=ex.Message,message="As observações de um atendimento encerrado não podem ser alteradas."});}}
 private static async Task<IResult> GetByAppointmentAsync(Guid appointmentId,ClaimsPrincipal user,ServiceSessionService service,CancellationToken ct){var result=await service.GetByAppointmentAsync(GroupId(user),appointmentId,ct);if(result is null)return Results.NotFound();if(!CanAccess(user,result.ProfessionalUserId))return Results.Forbid();return Results.Ok(result);}
 private static async Task<IResult> AddItemAsync(Guid id,AddServiceSessionItemRequest request,HttpRequest httpRequest,ClaimsPrincipal user,ServiceSessionService service,IConfiguration configuration,CancellationToken ct){var current=await service.GetAsync(GroupId(user),id,ct);if(current is null)return Results.NotFound();if(!CanAccess(user,current.ProfessionalUserId))return Results.Forbid();var canDiscount=await CanDiscountAsync(user,configuration,ct);try{var key=ServiceSessionIdempotency.RequireKey(httpRequest);return Results.Created($"/api/v1/service-sessions/{id}/items",await service.AddItemAsync(GroupId(user),id,UserId(user),request,canDiscount,key,ct));}catch(UnauthorizedAccessException ex)when(ex.Message=="DISCOUNT_NOT_ALLOWED"){return Results.Forbid();}catch(InvalidOperationException ex)when(ex.Message=="SERVICE_SESSION_CLOSED"){return Results.Conflict(new{code=ex.Message,message="O atendimento já está encerrado."});}catch(InvalidOperationException ex)when(ex.Message is "IDEMPOTENCY_KEY_REUSED" or "IDEMPOTENCY_REQUEST_IN_PROGRESS"){return Results.Conflict(new{code=ex.Message,message="A chave de idempotência já está associada a outra inclusão ou ainda está em processamento."});}catch(ArgumentException ex)when(ex.Message is "IDEMPOTENCY_KEY_REQUIRED" or "IDEMPOTENCY_KEY_INVALID"){return Results.BadRequest(new{code=ex.Message,message="A inclusão exige uma chave de idempotência válida."});}catch(ArgumentException ex){return Results.BadRequest(new{code="VALIDATION_ERROR",message=ex.Message});}}
 private static async Task<IResult> FinishAsync(Guid id,FinishServiceSessionRequest request,HttpRequest httpRequest,ClaimsPrincipal user,ServiceSessionService service,CancellationToken ct){var current=await service.GetAsync(GroupId(user),id,ct);if(current is null)return Results.NotFound();if(!CanAccess(user,current.ProfessionalUserId))return Results.Forbid();try{var key=ServiceSessionIdempotency.RequireKey(httpRequest);return Results.Ok(await service.FinishAsync(GroupId(user),id,UserId(user),request,key,ct));}catch(ArgumentException ex)when(ex.Message is "IDEMPOTENCY_KEY_REQUIRED" or "IDEMPOTENCY_KEY_INVALID"){return Results.BadRequest(new{code=ex.Message,message="A finalização exige uma chave de idempotência válida."});}catch(InvalidOperationException ex)when(ex.Message is "IDEMPOTENCY_KEY_REUSED" or "IDEMPOTENCY_REQUEST_IN_PROGRESS"){return Results.Conflict(new{code=ex.Message,message="A chave de idempotência já está associada a outra finalização ou ainda está em processamento."});}catch(InvalidOperationException ex)when(ex.Message is "SERVICE_SESSION_CLOSED" or "APPOINTMENT_MUST_BE_IN_SERVICE"){return Results.Conflict(new{code=ex.Message,message="O atendimento não pode ser finalizado no estado atual."});}}
 private static bool CanAccess(ClaimsPrincipal user,Guid professionalId)=>IsAdmin(user)||UserId(user)==professionalId;private static bool IsAdmin(ClaimsPrincipal user)=>string.Equals(user.FindFirstValue("profile"),"ADMIN",StringComparison.OrdinalIgnoreCase);private static Guid GroupId(ClaimsPrincipal user)=>Guid.Parse(user.FindFirstValue("group_id")??throw new UnauthorizedAccessException());private static Guid UserId(ClaimsPrincipal user)=>Guid.Parse(user.FindFirstValue(ClaimTypes.NameIdentifier)??user.FindFirstValue("sub")??throw new UnauthorizedAccessException());private static string ConnectionString(IConfiguration configuration)=>configuration.GetConnectionString("Postgres")??Environment.GetEnvironmentVariable("BCK_POSTGRES_CONNECTION")??throw new InvalidOperationException("PostgreSQL connection is not configured.");private static async Task<Guid?> AppointmentProfessionalAsync(Guid appointmentId,Guid groupId,IConfiguration configuration,CancellationToken ct){await using var connection=new NpgsqlConnection(ConnectionString(configuration));await connection.OpenAsync(ct);await using var command=new NpgsqlCommand("SELECT professional_user_id FROM appointment WHERE id=$1 AND group_id=$2",connection);command.Parameters.AddWithValue(appointmentId);command.Parameters.AddWithValue(groupId);var value=await command.ExecuteScalarAsync(ct);return value is Guid id?id:null;}private static async Task<bool> CanDiscountAsync(ClaimsPrincipal user,IConfiguration configuration,CancellationToken ct){if(IsAdmin(user))return true;await using var connection=new NpgsqlConnection(ConnectionString(configuration));await connection.OpenAsync(ct);const string sql="SELECT EXISTS(SELECT 1 FROM user_permission up JOIN permission p ON p.id=up.permission_id JOIN bck_user bu ON bu.id=up.user_id WHERE up.user_id=$1 AND bu.group_id=$2 AND bu.active=true AND up.granted=true AND p.code='ALLOW_PRICE_OVERRIDE')";await using var command=new NpgsqlCommand(sql,connection);command.Parameters.AddWithValue(UserId(user));command.Parameters.AddWithValue(GroupId(user));return(bool)(await command.ExecuteScalarAsync(ct))!;}
}
